resource "aws_secretsmanager_secret" "database-secret" {
  name                    = "database-secret"
  recovery_window_in_days = 0
  tags = {
    Name = "Database Secret"
  }

}

resource "aws_secretsmanager_secret_version" "database-secret" {
  secret_id     = aws_secretsmanager_secret.database-secret.id
  secret_string = random_password.database-secret.result
}

resource "aws_secretsmanager_secret" "corporate-domain-admin-password" {
  name                    = "DomainAdministrator-Credentials"

  recovery_window_in_days = 0
  tags = {
    Name = "Corporate Domain Admin Password"
  }

}

resource "aws_secretsmanager_secret_version" "corporate-domain-admin-password" {
  secret_id     = aws_secretsmanager_secret.corporate-domain-admin-password.id
  secret_string = "FLAG{backwards::IfYouFindSomethingInterstingFindWhoHasAccessToIt}"
}

//create a policy that only has access to the corporate-domain-admin-password secret
resource "aws_iam_policy" "corporate-domain-admin-password-policy" {
  name        = "corporate-domain-admin-password-policy"
  path        = "/"
  description = "policy that only allows access to the corporate-domain-admin-password secret"

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "secretsmanager:GetSecretValue"
        ],
        "Resource" : [
          aws_secretsmanager_secret.corporate-domain-admin-password.arn
        ]
      }
    ]
  })
}

//create iam role that trusts the ctf starting user and attach the policy to it
resource "aws_iam_role" "Alexander-Arnold" {
  name               = "Alexander-Arnold"
  assume_role_policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Principal" : {
          "AWS" : [
            "arn:aws:iam::${var.account_id}:user/${var.ctf_starting_user_name}"
          ]
        },
        "Action" : [
          "sts:AssumeRole"
        ]
      }
    ]
  })
}

//attach the policy to the role
resource "aws_iam_role_policy_attachment" "corporate-domain-admin-password-policy-attachment" {
  role       = aws_iam_role.Alexander-Arnold.name
  policy_arn = aws_iam_policy.corporate-domain-admin-password-policy.arn
}

variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "account_id" {
  description = "This is the ID of the caller account"
  type        = string
  default     = ""
}


variable "shared_high_priv_servicerole" {
  description = "This is the arn of high priv service role that is attached to lambda's ec2's, etc. to facilitate privesc"
  type        = string
  default     = ""
}

variable "AWS_REGION" {
  type    = string
  default = "us-west-2"
}

# Resources
resource "random_password" "database-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_password" "app-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_string" "resource-suffix" {
  length           = 5 
  upper = false 
  special = false
}

variable "user_ip" {
  description = "The current user's IP address"
  type        = string
  default     = ""
}

variable "ctf_starting_user_arn" {
  description = "The arn of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}

variable "ctf_starting_user_name" {
  description = "The name of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}
